```rust
use thiserror::Error;

#[derive(Debug, PartialEq)]
pub enum Setting {
    MaxConnections(u32),
    Hostname(String),
    TlsEnabled(bool),
}

#[derive(Debug, Error, PartialEq)]
pub enum ParseError {
    #[error("missing '=' in line: {0:?}")]
    NoEquals(String),
    #[error("unknown key: {0:?}")]
    UnknownKey(String),
    #[error("invalid value for {key:?}: {value:?}")]
    BadValue { key: String, value: String },
}

pub fn parse_line(line: &str) -> Result<Setting, ParseError> {
    let line = line.trim();
    let (key, value) = line
        .split_once('=')
        .ok_or_else(|| ParseError::NoEquals(line.to_string()))?;
    let key = key.trim();
    let value = value.trim();

    let bad = || ParseError::BadValue { key: key.to_string(), value: value.to_string() };

    match key {
        "max_connections" => value.parse::<u32>().map(Setting::MaxConnections).map_err(|_| bad()),
        "hostname" => Ok(Setting::Hostname(value.to_string())),
        "tls_enabled" => match value {
            "true" | "1" | "on" => Ok(Setting::TlsEnabled(true)),
            "false" | "0" | "off" => Ok(Setting::TlsEnabled(false)),
            _ => Err(bad()),
        },
        other => Err(ParseError::UnknownKey(other.to_string())),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_each_key() {
        assert_eq!(parse_line("max_connections = 100"), Ok(Setting::MaxConnections(100)));
        assert_eq!(parse_line("tls_enabled=on"), Ok(Setting::TlsEnabled(true)));
    }

    #[test]
    fn rejects_garbage() {
        assert_eq!(parse_line("max_connections=abc"),
            Err(ParseError::BadValue { key: "max_connections".into(), value: "abc".into() }));
        assert!(matches!(parse_line("noequals"), Err(ParseError::NoEquals(_))));
    }
}
```

split_once handles values that themselves contain '=' (like a base64 blob) correctly since it only splits on the first one. Each error variant carries the offending input so the message points at the exact line and value. The tests cover the happy path per key and the two malformed-input classes.

Here's the debounce utility:

```typescript
interface Debved<F extends (...args: any[]) => void> {
  (...args: Parameters<F>): void;
  cancel(): void;
  flush(): void;
}

interface Options {
  leading?: boolean;
  trailing?: boolean;
}

export function debounce<F extends (...args: any[]) => void>(
  fn: F,
  wait: number,
  { leading = false, trailing = true }: Options = {},
): Debved<F> {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<F> | null = null;

  const debounced = (...args: Parameters<F>) => {
    lastArgs = args;
    const callNow = leading && timer === null;

    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (trailing && lastArgs && !callNow) {
        fn(...lastArgs);
      }
      lastArgs = null;
    }, wait);

    if (callNow) fn(...args);
  };

  debounced.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = null;
    lastArgs = null;
  };

  debounced.flush = () => {
    if (timer && trailing && lastArgs) {
      clearTimeout(timer);
      timer = null;
      fn(...lastArgs);
      lastArgs = null;
    }
  };

  return debounced as Debved<F>;
}
```

Semantics: with the defaults (leading false, trailing true) it behaves like the classic debounce — fires once, wait ms after the last call. leading:true fires immediately on the first call of a burst and suppresses the trailing call so you don't get two invocations. cancel() drops any pending trailing call (handy in a React cleanup). flush() forces a pending call to run now. The callNow guard is what prevents the double-fire when leading is on: it records that the leading edge already fired so the timer's trailing branch skips it.

