Here's the working implementation:

```javascript
const sharp = require('sharp');

async function generateThumbnail(imageBytes, size = 200) {
  if (!Buffer.isBuffer(imageBytes) || imageBytes.length === 0) {
    throw new TypeError('generateThumbnail: expected a non-empty Buffer');
  }
  try {
    return await sharp(imageBytes)
      .rotate()                       // respect EXIF orientation before resizing
      .resize(size, size, { fit: 'cover', position: 'attention' })
      .jpeg({ quality: 80, mozjpeg: true })
      .toBuffer();
  } catch (err) {
    // sharp throws on unsupported/corrupt input; make it actionable
    throw new Error(`thumbnail generation failed: ${err.message}`, { cause: err });
  }
}

async function makeThumbnails(files, concurrency = 4) {
  const out = [];
  for (let i = 0; i < files.length; i += concurrency) {
    const batch = files.slice(i, i + concurrency);
    const thumbs = await Promise.all(
      batch.map(async (f) => ({ name: f.name, thumb: await generateThumbnail(f.bytes) })),
    );
    out.push(...thumbs);
  }
  return out;
}

module.exports = { generateThumbnail, makeThumbnails };
```

Details that matter: .rotate() with no args reads EXIF orientation and bakes it in before the resize, so portrait phone photos don't come out sideways — a bug people hit constantly. fit: 'cover' with position: 'attention' crops to the most feature-rich region rather than a naive center crop. mozjpeg gets you smaller files at the same visual quality. Invalid input (non-Buffer, empty, or corrupt image data) throws a clear error with the original as cause rather than returning garbage. makeThumbnails processes in batches of 4 so a large upload set doesn't spawn hundreds of concurrent sharp pipelines and exhaust memory.

