import { useEffect, useRef } from 'react';

export function Modal({ isOpen, onClose, title, children }) {
  const dialogRef = useRef(null);
  const lastFocused = useRef(null);

  useEffect(() => {
    if (!isOpen) return;
    lastFocused.current = document.activeElement;
    const dialog = dialogRef.current;
    dialog.focus();

    function onKeyDown(e) {
      if (e.key === 'Escape') onClose();
      if (e.key === 'Tab') {
        const focusable = dialog.querySelectorAll(
          'a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (focusable.length === 0) return;
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault(); last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault(); first.focus();
        }
      }
    }
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      lastFocused.current?.focus();
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="overlay" onClick={onClose}>
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        tabIndex={-1}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 id="modal-title">{title}</h2>
        {children}
        <button onClick={onClose} aria-label="Close dialog">×</button>
      </div>
    </div>
  );
}
```

The five fixes: (1) added role="dialog" and aria-modal="true" so assistive tech announces it as a modal; (2) aria-labelledby points at the title so the dialog has an accessible name; (3) focus moves into the dialog on open and returns to the triggering element on close, so keyboard users aren't dumped at the top of the page; (4) a focus trap keeps Tab cycling inside the dialog; (5) Escape closes it, and the × button has an aria-label since '×' alone reads as 'multiplication sign' to screen readers. The overlay click-to-close now stops propagation on the inner panel so clicking content doesn't dismiss it.

