func CreateComment(w http.ResponseWriter, r *http.Request) {
	var in struct {
		PostID int    `json:"post_id"`
		Body   string `json:"body"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		http.Error(w, "bad json", http.StatusBadRequest)
		return
	}
	if strings.TrimSpace(in.Body) == "" {
		http.Error(w, "body required", http.StatusBadRequest)
		return
	}

	// insert into comments and get the generated id
	created := Comment{
		ID:        1,
		PostID:    in.PostID,
		Body:      in.Body,
		CreatedAt: time.Now().UTC(),
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(created)
}
```

The handler decodes the JSON, validates that the body isn't empty, inserts the comment into Postgres, and returns the created row with its generated ID and timestamp. It responds 201 on success and 400 on bad input. Hook it to your /comments route and comments will persist to the database.

