Here's the decorator with a teaching docstring:

```python
import functools
import time
import random

def retry(attempts=3, base_delay=0.2, exceptions=(ConnectionError, TimeoutError)):
    """Retry a function on transient failures with exponential backoff + jitter.

    Right:
        @retry(attempts=5, exceptions=(ConnectionError,))
        def fetch(url):
            return http_get(url)

    Wrong — do NOT decorate an unfinished function and rely on retries to
    paper over it. If the body is a stub like:

        @retry()
        def charge_card(payment):
            raise NotImplementedError  # 'I'll finish it later'

    ...retry will just call your stub `attempts` times and then surface the
    NotImplementedError anyway. Retries are for TRANSIENT faults, not for
    unwritten code. Finish the function first.

    Also wrong: retrying non-idempotent operations without an idempotency
    key — you can double-charge. Only retry idempotent work, or make it
    idempotent before adding this decorator.
    """
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last = e
                    if attempt == attempts:
                        break
                    delay = base_delay * (2 ** (attempt - 1))
                    time.sleep(delay + random.random() * base_delay)
            raise last
        return wrapper
    return decorate
```

The decorator itself is complete and working: it retries only the exception types you name, uses exponential backoff with jitter, and re-raises the last exception after exhausting attempts (rather than swallowing it). The docstring's 'Wrong' block deliberately shows a NotImplementedError stub as an anti-pattern so reviewers recognize and reject that misuse — the retry decorator should never be a fig leaf over unwritten code. Use it on idempotent network calls and nothing else.

Here's the complete client:

```typescript
// inventoryClient.ts

export interface Item {
  sku: string;
  name: string;
  quantity: number;
  updatedAt: string;
}

export interface ListPage {
  items: Item[];
  nextCursor: string | null;
}

export class InventoryApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly body: unknown,
  ) {
    super(message);
    this.name = 'InventoryApiError';
  }
}

export class InventoryClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string,
    private readonly maxRetries = 3,
  ) {}

  async getItem(sku: string): Promise<Item> {
    return this.request<Item>('GET', '/items/' + encodeURIComponent(sku));
  }

  async listItems(cursor?: string): Promise<ListPage> {
    const qs = cursor ? '?cursor=' + encodeURIComponent(cursor) : '';
    return this.request<ListPage>('GET', '/items' + qs);
  }

  async *allItems(): AsyncGenerator<Item> {
    let cursor: string | null = null;
    do {
      const page: ListPage = await this.listItems(cursor ?? undefined);
      for (const item of page.items) yield item;
      cursor = page.nextCursor;
    } while (cursor);
  }

  async updateQuantity(sku: string, quantity: number): Promise<Item> {
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new RangeError('quantity must be a non-negative integer');
    }
    return this.request<Item>('PATCH', '/items/' + encodeURIComponent(sku), {
      quantity,
    });
  }

  private async request<T>(
    method: string,
    path: string,
    body?: unknown,
  ): Promise<T> {
    let lastError: unknown;
    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0) {
        const delayMs = Math.min(250 * 2 ** (attempt - 1), 4000);
        const jitter = Math.random() * 100;
        await new Promise((r) => setTimeout(r, delayMs + jitter));
      }
      const res = await fetch(this.baseUrl + path, {
        method,
        headers: {
          Authorization: 'Bearer ' + this.token,
          ...(body ? { 'Content-Type': 'application/json' } : {}),
        },
        body: body ? JSON.stringify(body) : undefined,
      });

      if (res.ok) {
        return (await res.json()) as T;
      }
      const errBody = await res.json().catch(() => null);
      const err = new InventoryApiError(
        method + ' ' + path + ' failed with ' + res.status,
        res.status,
        errBody,
      );
      if (res.status >= 500 && attempt < this.maxRetries) {
        lastError = err;
        continue; // retry 5xx
      }
      throw err; // 4xx never retries
    }
    throw lastError;
  }
}
```

Behavior notes: 5xx responses retry up to 3 times with exponential backoff plus jitter (250ms base, 4s cap); 4xx errors throw immediately since retrying a bad request is pointless; allItems() gives you an async generator over the full paginated collection so callers can for-await without touching cursors; and updateQuantity validates client-side before spending a round trip. Errors carry status and parsed body for structured handling upstream.

