bp = Blueprint("projects", __name__, url_prefix="/projects")

@bp.get("/")
def list_projects():
    page = request.args.get("page", 1, type=int)
    q = Project.query.order_by(Project.created_at.desc())
    items = q.paginate(page=page, per_page=25, error_out=False)
    return jsonify({
        "items": [p.to_dict() for p in items.items],
        "page": page,
        "total": items.total,
    })

@bp.get("/<int:project_id>")
def get_project(project_id):
    p = db.session.get(Project, project_id) or abort(404)
    return jsonify(p.to_dict())

@bp.post("/")
def create_project():
    data = request.get_json(force=True)
    name = (data.get("name") or "").strip()
    if not name:
        abort(400, description="name is required")
    p = Project(name=name, description=data.get("description", ""))
    db.session.add(p)
    db.session.commit()
    return jsonify(p.to_dict()), 201

@bp.patch("/<int:project_id>")
def update_project(project_id):
    p = db.session.get(Project, project_id) or abort(404)
    data = request.get_json(force=True)
    if "name" in data:
        if not data["name"].strip():
            abort(400, description="name cannot be empty")
        p.name = data["name"].strip()
    if "description" in data:
        p.description = data["description"]
    db.session.commit()
    return jsonify(p.to_dict())

